import{_ as o,l as r,o as e,c as l,v as t,p as n,x as i,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"调度域与拓扑","description":"","frontmatter":{"title":"调度域与拓扑","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sched-domains.md","filePath":"cs/sched-domains.md","lastUpdated":1789023840000}'),h={name:"cs/sched-domains.md"};function m(u,a,_,A,f,E){const s=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="调度域与拓扑" tabindex="-1">调度域与拓扑 <a class="header-anchor" href="#调度域与拓扑" aria-label="Permalink to &quot;调度域与拓扑&quot;">​</a></h1><div class="epigraph"><p>调度域按 SMT、核、LLC、NUMA 分层：负载均衡先在小域做，跨节点迁移更贵，所以更懒。</p><footer>—— 据 Linux 对 sched domains 的文档；Lameter 对 NUMA 的论述；[NUMA 策略](/cs/numa-mempolicy) 为内存侧先修</footer></div><p><a href="/cs/eevdf">EEVDF</a> 在单队列上选任务。多核要 <strong>在哪一 CPU 上跑</strong>。缺口是调度域：拓扑感知的负载均衡，不是再讲 vruntime。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每次 tick 若在全机找最闲 CPU，锁和缓存都炸。域：SMT 兄弟 → 共享 L2/L3 的核 → NUMA 节点 → 机器。均衡周期与阈值随层变。缺口：新任务 wake 的选核（wake_affine）；idle 平衡；与 cpuset 缩小的域。本课不把每个 <code>SD_FLAG</code> 背完。</p><p><span class="marginnote">非对称核（大核小核）在异构课。这里先钉对称拓扑层。IRQ 与 NAPI 亲和是另一条线，但同拓扑。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>load_balance</code>：在某域找忙组与闲组，拉任务。跨 NUMA：考虑页所在节点（与 mempolicy 互动）。对照 <a href="/cs/rss-multiqueue">RSS</a>：包绑队列；任务绑 CPU，可迁移。对照 <a href="/cs/page-migration-compaction">compaction</a>：一个迁页，一个迁任务。</p>',8)),(e(),n(p,null,{default:i(()=>[c(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SMT%5B%22SMT%20%E5%9F%9F%22%5D%20--%3E%20CORE%5B%22%E6%A0%B8%20%2F%20LLC%20%E5%9F%9F%22%5D%0A%20%20CORE%20--%3E%20NUMA%5B%22NUMA%20%E5%9F%9F%22%5D%0A%20%20NUMA%20--%3E%20LB%5B%22%E5%88%86%E5%B1%82%E8%B4%9F%E8%BD%BD%E5%9D%87%E8%A1%A1%22%5D%0A%20%20WAKE%5B%22%E5%94%A4%E9%86%92%22%5D%20--%3E%20AFF%5B%22wake%20%E9%80%89%E6%A0%B8%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>调度域把「多核是一棵延迟树」收成均衡策略，使共享缓存的迁移优先于跨节点。这是吞吐与延迟的几何。不要写成主板购物。与 <a href="/cs/kpti-os">KPTI</a>：迁移后 TLB 本来就要重建。</p><p>错误拓扑（固件错报）会导致永远跨节点蹦，看起来像性能 bug。</p><p>实现上：固件把不共享缓存的核标成共享，均衡会打错。cpuset 缩小域后，孤立的 CPU 不再参与全局 steal。新任务 wake_affine 优先唤醒者的 LLC 域。 读法上只引用<a href="/cs/eevdf">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>调度域与拓扑</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cluster scheduling 的全部新层。不保证虚拟机里暴露的拓扑真实。下一课在拓扑上再叠能耗：EAS。</p><p>版本字段会变，课序钉的是机制对象「调度域与拓扑」，不是某一主线内核的结构体名。 后课默认：迁移按域分层。按能耗模型选核，下一课 EAS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>调度域镜像 SMT/LLC/NUMA 层次。</li><li>均衡与唤醒选核都看域。</li><li>EAS 是下一课。</li><li>出处：Linux sched-domains；Lameter NUMA。</li></ul>',11))])}const P=o(h,[["render",m]]);export{S as __pageData,P as default};
